import Foundation
import Testing

@testable import AnyLanguageModel

@Generable(description: "A contact")
private struct ImplicitNilContact {
    var name: String
    var nickname: String?
    var tags: [String]?
}

@Generable(description: "A contact", representNilExplicitlyInGeneratedContent: true)
private struct ExplicitNilContact {
    var name: String
    var nickname: String?
    var tags: [String]?
}

@Generable(description: "A place", representNilExplicitlyInGeneratedContent: true)
private struct ExplicitNilPlace {
    var name: String
    var zone: String?
    var alias: String?
}

@Generable(description: "A greeting", representNilExplicitlyInGeneratedContent: true)
private struct ExplicitNilGreeting {
    var salutation: String?
    var name: String
}

@Suite("Explicit nil")
struct ExplicitNilTests {
    @Test func nilOptionalPropertiesAreLeftOutByDefault() throws {
        let contact = ImplicitNilContact(name: "Alice", nickname: nil, tags: nil)
        guard case .structure(let properties, let orderedKeys) = contact.generatedContent.kind else {
            Issue.record("Expected structured content")
            return
        }
        #expect(properties.keys.sorted() == ["name"])
        #expect(orderedKeys == ["name"])
        #expect(contact.generatedContent == (try ImplicitNilContact(contact.generatedContent)).generatedContent)
    }

    @Test func nilOptionalPropertiesAreNullWhenExplicit() throws {
        let contact = ExplicitNilContact(name: "Alice", nickname: nil, tags: nil)
        guard case .structure(let properties, let orderedKeys) = contact.generatedContent.kind else {
            Issue.record("Expected structured content")
            return
        }
        #expect(properties["nickname"]?.kind == .null)
        #expect(properties["tags"]?.kind == .null)
        #expect(orderedKeys == ["name", "nickname", "tags"])
    }

    @Test func setOptionalPropertiesAreIncludedEitherWay() {
        let implicit = ImplicitNilContact(name: "Alice", nickname: "Al", tags: ["friend"])
        let explicit = ExplicitNilContact(name: "Alice", nickname: "Al", tags: ["friend"])
        #expect(implicit.generatedContent == explicit.generatedContent)
    }

    @Test func bothFormsDecode() throws {
        let omitted = try GeneratedContent(json: #"{"name": "Alice"}"#)
        let null = try GeneratedContent(json: #"{"name": "Alice", "nickname": null, "tags": null}"#)
        for content in [omitted, null] {
            let implicit = try ImplicitNilContact(content)
            let explicit = try ExplicitNilContact(content)
            #expect(implicit.nickname == nil && implicit.tags == nil)
            #expect(explicit.nickname == nil && explicit.tags == nil)
        }
    }

    @Test func flagDoesNotChangeEncodedSchema() throws {
        let properties = [
            GenerationSchema.Property(name: "name", type: String.self),
            GenerationSchema.Property(name: "nickname", type: String?.self),
        ]
        let implicit = GenerationSchema(type: ImplicitNilContact.self, properties: properties)
        let explicit = GenerationSchema(
            type: ImplicitNilContact.self,
            representNilExplicitlyInGeneratedContent: true,
            properties: properties
        )
        let encoder = JSONEncoder()
        encoder.outputFormatting = .sortedKeys
        #expect(try encoder.encode(implicit) == encoder.encode(explicit))
    }

    @Test func schemaFillsInNullForOmittedOptionalProperties() throws {
        let content = try GeneratedContent(json: #"{"name": "Alice"}"#)

        let explicit = ExplicitNilContact.generationSchema.representingNilExplicitly(in: content)
        guard case .structure(let properties, _) = explicit.kind else {
            Issue.record("Expected structured content")
            return
        }
        #expect(properties["nickname"]?.kind == .null)
        #expect(properties["tags"]?.kind == .null)
        #expect(properties["name"] == GeneratedContent("Alice"))

        #expect(ImplicitNilContact.generationSchema.representingNilExplicitly(in: content) == content)
    }

    @Test func dynamicSchemaFillsInNullForOmittedOptionalProperties() throws {
        let contact = DynamicGenerationSchema(
            name: "Contact",
            representNilExplicitlyInGeneratedContent: true,
            properties: [
                .init(name: "name", schema: .init(type: String.self)),
                .init(name: "nickname", schema: .init(type: String.self), isOptional: true),
            ]
        )
        let schema = try GenerationSchema(root: contact, dependencies: [])
        let content = schema.representingNilExplicitly(in: try GeneratedContent(json: #"{"name": "Alice"}"#))
        guard case .structure(let properties, _) = content.kind else {
            Issue.record("Expected structured content")
            return
        }
        #expect(properties["nickname"]?.kind == .null)
    }

    @Test func nullableUnionFillsInNullForTheObjectVariant() throws {
        let contact = DynamicGenerationSchema(
            name: "Contact",
            representNilExplicitlyInGeneratedContent: true,
            properties: [
                .init(name: "name", schema: .init(type: String.self)),
                .init(name: "nickname", schema: .init(type: String.self), isOptional: true),
            ]
        )
        let nullableContact = DynamicGenerationSchema(name: "NullableContact", anyOf: [contact, .null])
        let schema = try GenerationSchema(root: nullableContact, dependencies: [])

        let content = schema.representingNilExplicitly(in: try GeneratedContent(json: #"{"name": "Alice"}"#))
        guard case .structure(let properties, _) = content.kind else {
            Issue.record("Expected structured content")
            return
        }
        #expect(properties["nickname"]?.kind == .null)

        let null = GeneratedContent(kind: .null)
        #expect(schema.representingNilExplicitly(in: null) == null)
    }

    @Test func unionSkipsObjectVariantsWithMissingRequiredProperties() throws {
        let person = DynamicGenerationSchema(
            name: "Person",
            properties: [
                .init(name: "name", schema: .init(type: String.self)),
                .init(name: "age", schema: .init(type: Int.self)),
            ]
        )
        let contact = DynamicGenerationSchema(
            name: "Contact",
            representNilExplicitlyInGeneratedContent: true,
            properties: [
                .init(name: "name", schema: .init(type: String.self)),
                .init(name: "nickname", schema: .init(type: String.self), isOptional: true),
            ]
        )
        let either = DynamicGenerationSchema(name: "Either", anyOf: [person, contact])
        let schema = try GenerationSchema(root: either, dependencies: [])

        let content = schema.representingNilExplicitly(in: try GeneratedContent(json: #"{"name": "Alice"}"#))
        guard case .structure(let properties, _) = content.kind else {
            Issue.record("Expected structured content")
            return
        }
        #expect(properties["nickname"]?.kind == .null)
    }

    @Test func nestedUnionFillsInNullForTheObjectVariant() throws {
        let contact = DynamicGenerationSchema(
            name: "Contact",
            representNilExplicitlyInGeneratedContent: true,
            properties: [
                .init(name: "name", schema: .init(type: String.self)),
                .init(name: "nickname", schema: .init(type: String.self), isOptional: true),
            ]
        )
        let nullableContact = DynamicGenerationSchema(name: "NullableContact", anyOf: [contact, .null])
        let outer = DynamicGenerationSchema(
            name: "Outer",
            anyOf: [
                DynamicGenerationSchema(type: String.self),
                DynamicGenerationSchema(referenceTo: "NullableContact"),
            ]
        )
        let schema = try GenerationSchema(root: outer, dependencies: [nullableContact])

        let content = schema.representingNilExplicitly(in: try GeneratedContent(json: #"{"name": "Alice"}"#))
        guard case .structure(let properties, _) = content.kind else {
            Issue.record("Expected structured content")
            return
        }
        #expect(properties["nickname"]?.kind == .null)
    }

    @Test func filledInPropertiesFollowDeclarationOrder() throws {
        let content = try GeneratedContent(json: #"{"name": "Home"}"#)
        let filled = ExplicitNilPlace.generationSchema.representingNilExplicitly(in: content)
        #expect(filled == ExplicitNilPlace(name: "Home", zone: nil, alias: nil).generatedContent)
    }

    @Test func filledInPropertiesKeepDeclarationOrderAroundPresentProperties() throws {
        let content = try GeneratedContent(json: #"{"name": "Alice"}"#)
        let filled = ExplicitNilGreeting.generationSchema.representingNilExplicitly(in: content)
        #expect(filled == ExplicitNilGreeting(salutation: nil, name: "Alice").generatedContent)
    }

    @Test func propertyOrderIsPartOfExplicitNilSchemaEquality() {
        let name = GenerationSchema.Property(name: "name", type: String.self)
        let nickname = GenerationSchema.Property(name: "nickname", type: String?.self)
        let first = GenerationSchema(
            type: ImplicitNilContact.self,
            representNilExplicitlyInGeneratedContent: true,
            properties: [name, nickname]
        )
        let second = GenerationSchema(
            type: ImplicitNilContact.self,
            representNilExplicitlyInGeneratedContent: true,
            properties: [nickname, name]
        )
        #expect(first != second)
        #expect(
            GenerationSchema(type: ImplicitNilContact.self, properties: [name, nickname])
                == GenerationSchema(type: ImplicitNilContact.self, properties: [nickname, name])
        )
    }

    @Test func flagIsPartOfSchemaEquality() {
        let properties = [GenerationSchema.Property(name: "nickname", type: String?.self)]
        let implicit = GenerationSchema(type: ImplicitNilContact.self, properties: properties)
        let explicit = GenerationSchema(
            type: ImplicitNilContact.self,
            representNilExplicitlyInGeneratedContent: true,
            properties: properties
        )
        #expect(implicit != explicit)
    }

    @Test func streamedResponseCollectsNullForOmittedOptionalProperties() async throws {
        let model = MockLanguageModel { _, _ in #"{"name": "Alice"}"# }
        let session = LanguageModelSession(model: model)

        let response = try await session.streamResponse(to: "Who?", generating: ExplicitNilContact.self).collect()
        guard case .structure(let properties, _) = response.rawContent.kind else {
            Issue.record("Expected structured content")
            return
        }
        #expect(properties["nickname"]?.kind == .null)
        #expect(lastResponseText(in: session)?.contains(#""nickname":null"#) == true)
    }

    @Test func schemaResponsesReturnNullInContent() async throws {
        let contact = DynamicGenerationSchema(
            name: "Contact",
            representNilExplicitlyInGeneratedContent: true,
            properties: [
                .init(name: "name", schema: .init(type: String.self)),
                .init(name: "nickname", schema: .init(type: String.self), isOptional: true),
            ]
        )
        let schema = try GenerationSchema(root: contact, dependencies: [])
        let model = MockLanguageModel { _, _ in #"{"name": "Alice"}"# }

        let response = try await LanguageModelSession(model: model).respond(to: "Who?", schema: schema)
        #expect(response.content == response.rawContent)
        guard case .structure(let properties, _) = response.content.kind else {
            Issue.record("Expected structured content")
            return
        }
        #expect(properties["nickname"]?.kind == .null)

        let streamed = try await LanguageModelSession(model: model).streamResponse(to: "Who?", schema: schema)
            .collect()
        #expect(streamed.content == streamed.rawContent)
    }

    @Test func finalStreamedSnapshotHasNullInPartialContent() async throws {
        // Providers build partial content from the raw JSON, without normalizing it.
        let session = LanguageModelSession(model: RawPartialStreamingModel(json: #"{"name": "Alice"}"#))

        var last: LanguageModelSession.ResponseStream<ExplicitNilContact>.Snapshot?
        for try await snapshot in session.streamResponse(to: "Who?", generating: ExplicitNilContact.self) {
            last = snapshot
        }
        let snapshot = try #require(last)
        guard case .structure(let properties, _) = snapshot.content.generatedContent.kind else {
            Issue.record("Expected structured content")
            return
        }
        #expect(properties["nickname"]?.kind == .null)
        #expect(snapshot.content.generatedContent == snapshot.rawContent)
    }

    @Test func sessionRecordsNullForOmittedOptionalProperties() async throws {
        let model = MockLanguageModel { _, _ in #"{"name": "Alice"}"# }

        let explicitSession = LanguageModelSession(model: model)
        let explicit = try await explicitSession.respond(to: "Who?", generating: ExplicitNilContact.self)
        #expect(explicit.rawContent.jsonString.contains("nickname"))
        #expect(lastResponseText(in: explicitSession)?.contains(#""nickname":null"#) == true)

        let implicitSession = LanguageModelSession(model: model)
        let implicit = try await implicitSession.respond(to: "Who?", generating: ImplicitNilContact.self)
        #expect(!implicit.rawContent.jsonString.contains("nickname"))
        #expect(lastResponseText(in: implicitSession)?.contains("nickname") == false)
    }

    private func lastResponseText(in session: LanguageModelSession) -> String? {
        guard case .response(let response)? = session.transcript.last,
            case .text(let text)? = response.segments.first
        else { return nil }
        return text.content
    }
}

/// A model that streams one snapshot whose partial content comes straight from the raw JSON.
private struct RawPartialStreamingModel: LanguageModel {
    typealias UnavailableReason = Never

    let json: String

    func respond<Content>(
        within session: LanguageModelSession,
        to prompt: Prompt,
        generating type: Content.Type,
        includeSchemaInPrompt: Bool,
        options: GenerationOptions
    ) async throws -> LanguageModelSession.Response<Content> where Content: Generable {
        fatalError("Not used")
    }

    func streamResponse<Content>(
        within session: LanguageModelSession,
        to prompt: Prompt,
        generating type: Content.Type,
        includeSchemaInPrompt: Bool,
        options: GenerationOptions
    ) -> sending LanguageModelSession.ResponseStream<Content> where Content: Generable {
        let json = json
        let stream = AsyncThrowingStream<LanguageModelSession.ResponseStream<Content>.Snapshot, any Error> {
            continuation in
            do {
                let rawContent = try GeneratedContent(json: json)
                continuation.yield(
                    .init(content: try Content.PartiallyGenerated(rawContent), rawContent: rawContent)
                )
                continuation.finish()
            } catch {
                continuation.finish(throwing: error)
            }
        }
        return LanguageModelSession.ResponseStream(stream: stream)
    }
}

import Foundation
import Testing

@testable import AnyLanguageModel

@Generable
private struct StringifiedToolArguments {
    var count: Int?
    var enabled: Bool?
    var ratio: Double?
}

@Suite("Primitive string coercion")
struct PrimitiveStringCoercionTests {
    @Test func decodesStringifiedNumbersAndBools() throws {
        #expect(try Int(GeneratedContent(kind: .string("5"))) == 5)
        #expect(try Int(GeneratedContent(kind: .string(" -12 "))) == -12)
        #expect(try Int(GeneratedContent(kind: .string("5.0"))) == 5)
        #expect(try Bool(GeneratedContent(kind: .string("true"))) == true)
        #expect(try Bool(GeneratedContent(kind: .string("False"))) == false)
        #expect(try Double(GeneratedContent(kind: .string("3.25"))) == 3.25)
        #expect(try Float(GeneratedContent(kind: .string("0.5"))) == 0.5)
        #expect(try Decimal(GeneratedContent(kind: .string("2.5"))) == Decimal(2.5))
    }

    @Test func rejectsUnparseableStrings() {
        #expect(throws: GeneratedContentError.self) {
            try Int(GeneratedContent(kind: .string("five")))
        }
        #expect(throws: GeneratedContentError.self) {
            try Int(GeneratedContent(kind: .string("5.5")))
        }
        #expect(throws: GeneratedContentError.self) {
            try Bool(GeneratedContent(kind: .string("yes")))
        }
        #expect(throws: GeneratedContentError.self) {
            try Double(GeneratedContent(kind: .string("")))
        }
    }

    @Test func nativeKindsStillDecode() throws {
        #expect(try Int(GeneratedContent(kind: .number(7))) == 7)
        #expect(try Bool(GeneratedContent(kind: .bool(true))) == true)
        #expect(try Double(GeneratedContent(kind: .number(1.5))) == 1.5)
        #expect(try String(GeneratedContent(kind: .string("text"))) == "text")
    }

    @Test func decodesGenerableArgumentsWithStringifiedValues() throws {
        let json = #"{"count": "3", "enabled": "true", "ratio": "0.75"}"#
        let arguments = try StringifiedToolArguments(GeneratedContent(json: json))

        #expect(arguments.count == 3)
        #expect(arguments.enabled == true)
        #expect(arguments.ratio == 0.75)
    }
}

import Testing

@testable import AnyLanguageModel

@Suite("Dynamic instructions builder")
struct DynamicInstructionsBuilderTests {
    @Test func builderComposesNestedConditionalEmptyAndToolArrayContent() {
        let resolved = AnyDynamicInstructions(erasing: Composition(enabled: true)).resolveForRequest()

        #expect(resolved.instructions?.description == "Outer\nNested\nFor each")
        #expect(resolved.tools.map(\.name) == ["tool-a", "tool-b"])
    }

    @Test func falseConditionLeavesOutItsContent() {
        let resolved = AnyDynamicInstructions(erasing: Composition(enabled: false)).resolveForRequest()

        #expect(resolved.instructions?.description == "Outer\nFor each")
        #expect(resolved.tools.isEmpty)
    }

    @Test func bodyIsEvaluatedOnEachResolution() {
        let counter = Counter()
        let dynamic = AnyDynamicInstructions(erasing: CountingInstructions(counter: counter))

        #expect(dynamic.resolveForRequest().instructions?.description == "Request 1")
        #expect(dynamic.resolveForRequest().instructions?.description == "Request 2")
    }

    @Test func nestingDoesNotChangeWhitespace() {
        let flat = AnyDynamicInstructions(erasing: Flat()).resolveForRequest()
        let nested = AnyDynamicInstructions(erasing: Outer()).resolveForRequest()

        #expect(flat.instructions?.description == "A\nB  \nC")
        #expect(nested.instructions?.description == flat.instructions?.description)
    }

    @Test func emptyBuilderResolvesToNothing() {
        let resolved = AnyDynamicInstructions(erasing: EmptyDynamicInstructions()).resolveForRequest()

        #expect(resolved.instructions == nil)
        #expect(resolved.tools.isEmpty)
    }
}

private struct Composition: DynamicInstructions {
    let enabled: Bool

    var body: some DynamicInstructions {
        Instructions("Outer")
        if enabled {
            Nested()
        }
        EmptyDynamicInstructions()
        ForEach([Item(id: 1, text: "For each")]) { item in
            Instructions(item.text)
        }
    }
}

private struct Flat: DynamicInstructions {
    var body: some DynamicInstructions {
        Instructions("A")
        Instructions("B  ")
        Instructions("C")
    }
}

private struct Outer: DynamicInstructions {
    var body: some DynamicInstructions {
        Instructions("A")
        Inner()
    }
}

private struct Inner: DynamicInstructions {
    var body: some DynamicInstructions {
        Instructions("B  ")
        Instructions("C")
    }
}

private struct Item: Identifiable {
    let id: Int
    let text: String
}

private struct Nested: DynamicInstructions {
    var body: some DynamicInstructions {
        Instructions("Nested")
        [NamedTool(name: "tool-a"), NamedTool(name: "tool-b")] as [any Tool]
    }
}

private struct NamedTool: Tool {
    let name: String
    let description = "A tool that returns its name"

    typealias Arguments = GeneratedContent

    var parameters: GenerationSchema {
        GeneratedContent.generationSchema
    }

    func call(arguments: GeneratedContent) async throws -> String {
        name
    }
}

private final class Counter: @unchecked Sendable {
    private let count = Locked(0)

    func next() -> Int {
        count.withLock { value in
            value += 1
            return value
        }
    }
}

private struct CountingInstructions: DynamicInstructions {
    let counter: Counter

    var body: some DynamicInstructions {
        Instructions("Request \(counter.next())")
    }
}

import Foundation
import Testing

@testable import AnyLanguageModel

@Suite("Dynamic instructions")
struct DynamicInstructionsTests {
    @Test func dynamicSessionLeavesInstructionsOutOfHistoryAndSessionProperties() {
        let state = DynamicFixtureState()
        let history: [Transcript.Entry] = [
            .instructions(Transcript.Instructions(segments: [.text(.init(content: "Old"))], toolDefinitions: [])),
            .prompt(Transcript.Prompt(segments: [.text(.init(content: "Hello"))])),
        ]
        let session = LanguageModelSession(
            model: DynamicContextModel(state: state, continuesAfterTool: false),
            dynamicInstructions: FixtureDynamicInstructions(state: state),
            history: history
        )

        #expect(session.instructions == nil)
        #expect(session.tools.isEmpty)
        #expect(session.transcript.count == 1)
        let context = session.resolvedRequestContext()
        #expect(context.instructions?.description == "Instructions A")
        #expect(context.transcript.count == 2)
    }

    @Test func bodyReevaluatesForEveryNonstreamingRequest() async throws {
        let state = DynamicFixtureState()
        let model = DynamicContextModel(state: state, continuesAfterTool: false)
        let session = LanguageModelSession(
            model: model,
            dynamicInstructions: FixtureDynamicInstructions(state: state)
        )

        #expect(state.evaluationCount == 0)
        _ = try await session.respond(to: "First")
        state.select(.b)
        _ = try await session.respond(to: "Second")

        #expect(
            model.snapshots.withLock { $0 } == [
                .init(instructions: "Instructions A", tools: ["tool-a"]),
                .init(instructions: "Instructions B", tools: ["tool-b"]),
            ]
        )
        #expect(state.evaluationCount == 2)
    }

    @Test func bodyReevaluatesForEveryStreamingRequest() async throws {
        let state = DynamicFixtureState()
        let model = DynamicContextModel(state: state, continuesAfterTool: false)
        let session = LanguageModelSession(
            model: model,
            dynamicInstructions: FixtureDynamicInstructions(state: state)
        )

        #expect(state.evaluationCount == 0)
        _ = try await session.streamResponse(to: "First").collect()
        state.select(.b)
        _ = try await session.streamResponse(to: "Second").collect()

        #expect(
            model.snapshots.withLock { $0 } == [
                .init(instructions: "Instructions A", tools: ["tool-a"]),
                .init(instructions: "Instructions B", tools: ["tool-b"]),
            ]
        )
        #expect(state.evaluationCount == 2)
    }

    @Test(arguments: [false, true])
    func toolContinuationReevaluatesAndExecutesProducingSnapshot(streaming: Bool) async throws {
        let state = DynamicFixtureState()
        let model = DynamicContextModel(state: state, continuesAfterTool: true)
        let session = LanguageModelSession(
            model: model,
            dynamicInstructions: FixtureDynamicInstructions(state: state)
        )

        if streaming {
            _ = try await session.streamResponse(to: "Use a tool").collect()
        } else {
            _ = try await session.respond(to: "Use a tool")
        }

        #expect(
            model.snapshots.withLock { $0 } == [
                .init(instructions: "Instructions A", tools: ["tool-a"]),
                .init(instructions: "Instructions B", tools: ["tool-b"]),
            ]
        )
        #expect(state.executedTools == ["tool-a"])
        #expect(state.evaluationCount == 2)
        #expect(session.transcript.count == 4)
        guard case .prompt = session.transcript[0],
            case .toolCalls(let calls) = session.transcript[1],
            case .toolOutput(let output) = session.transcript[2],
            case .response = session.transcript[3]
        else {
            Issue.record("Expected prompt, tool call, tool output, and response")
            return
        }
        #expect(calls.first?.id == output.id)
        #expect(output.toolName == "tool-a")
    }

    @Test func historyDoesNotPersistDynamicInstructionsAndRehydratesWithCurrentState() async throws {
        let state = DynamicFixtureState()
        let firstModel = DynamicContextModel(state: state, continuesAfterTool: false)
        let firstSession = LanguageModelSession(
            model: firstModel,
            dynamicInstructions: FixtureDynamicInstructions(state: state)
        )
        _ = try await firstSession.respond(to: "First")

        #expect(
            !firstSession.transcript.contains {
                if case .instructions = $0 { true } else { false }
            }
        )

        state.select(.b)
        let restoredModel = DynamicContextModel(state: state, continuesAfterTool: false)
        let restoredSession = LanguageModelSession(
            model: restoredModel,
            dynamicInstructions: FixtureDynamicInstructions(state: state),
            history: firstSession.transcript
        )
        _ = try await restoredSession.respond(to: "Second")

        #expect(
            restoredModel.snapshots.withLock { $0 } == [
                .init(instructions: "Instructions B", tools: ["tool-b"])
            ]
        )
        #expect(restoredSession.transcript.count == 4)
        #expect(
            !restoredSession.transcript.contains {
                if case .instructions = $0 { true } else { false }
            }
        )
    }

    @Test func builderComposesNestedConditionalEmptyAndToolArrayContent() {
        let state = DynamicFixtureState()
        let enabled = true
        let dynamic = AnyDynamicInstructions(erasing: FixtureComposition(state: state, enabled: enabled))
        let session = LanguageModelSession(
            model: DynamicContextModel(state: state, continuesAfterTool: false),
            dynamicInstructions: dynamic
        )

        let context = session.resolvedRequestContext()

        #expect(context.instructions?.description == "Outer\nNested\nFor each")
        #expect(context.tools.map(\.name) == ["tool-a", "tool-b"])
        #expect(session.transcript.isEmpty)
    }

    @Test func staticSessionRequestContextPreservesExistingBehavior() {
        let state = DynamicFixtureState()
        let tool = FixtureTool(name: "static-tool", state: state)
        let session = LanguageModelSession(
            model: DynamicContextModel(state: state, continuesAfterTool: false),
            tools: [tool],
            instructions: "Static"
        )

        let context = session.resolvedRequestContext()

        #expect(context.instructions?.description == "Static")
        #expect(context.tools.map(\.name) == ["static-tool"])
        #expect(context.transcript == session.transcript)
        #expect(session.instructions?.description == "Static")
        #expect(session.tools.map(\.name) == ["static-tool"])
    }

    @Test func failedResponseDoesNotReplayCompletedDynamicToolSideEffect() async throws {
        let state = DynamicFixtureState()
        let model = FailingAfterToolModel(state: state)
        let session = LanguageModelSession(
            model: model,
            dynamicInstructions: FixtureDynamicInstructions(state: state)
        )

        await #expect(throws: DynamicFixtureError.failed) {
            _ = try await session.respond(to: "Fail after tool")
        }
        _ = try await session.respond(to: "Retry")

        #expect(state.executedTools == ["tool-a"])
        #expect(
            model.snapshots.withLock { $0 } == [
                .init(instructions: "Instructions A", tools: ["tool-a"]),
                .init(instructions: "Instructions B", tools: ["tool-b"]),
            ]
        )
    }

    @Test func cancelledResponseDoesNotReplayCompletedDynamicToolSideEffect() async throws {
        let state = DynamicFixtureState()
        let control = DynamicCancellationControl()
        let model = CancellingAfterToolModel(state: state, control: control)
        let session = LanguageModelSession(
            model: model,
            dynamicInstructions: FixtureDynamicInstructions(state: state)
        )
        var started = control.started.makeAsyncIterator()

        let response = Task {
            try await session.respond(to: "Cancel after tool")
        }
        _ = await started.next()
        response.cancel()

        await #expect(throws: CancellationError.self) {
            _ = try await response.value
        }
        _ = try await session.respond(to: "Retry")

        #expect(state.executedTools == ["tool-a"])
        #expect(
            model.snapshots.withLock { $0 } == [
                .init(instructions: "Instructions A", tools: ["tool-a"]),
                .init(instructions: "Instructions B", tools: ["tool-b"]),
            ]
        )
    }
}

private struct FixtureDynamicInstructions: DynamicInstructions {
    let state: DynamicFixtureState

    var body: some DynamicInstructions {
        let snapshot = state.snapshotForEvaluation()
        Instructions(snapshot.instructions)
        [snapshot.tool]
    }
}

private struct FixtureComposition: DynamicInstructions {
    let state: DynamicFixtureState
    let enabled: Bool

    var body: some DynamicInstructions {
        Instructions("Outer")
        if enabled {
            NestedFixtureInstructions(state: state)
        }
        EmptyDynamicInstructions()
        ForEach([FixtureInstruction(id: 1, text: "For each")]) { item in
            Instructions(item.text)
        }
    }
}

private struct FixtureInstruction: Identifiable {
    let id: Int
    let text: String
}

private struct NestedFixtureInstructions: DynamicInstructions {
    let state: DynamicFixtureState

    var body: some DynamicInstructions {
        Instructions("Nested")
        [
            FixtureTool(name: "tool-a", state: state),
            FixtureTool(name: "tool-b", state: state),
        ] as [any Tool]
    }
}

private final class DynamicFixtureState: @unchecked Sendable {
    enum Selection: Sendable {
        case a
        case b
    }

    struct Storage: Sendable {
        var selection = Selection.a
        var evaluationCount = 0
        var executedTools: [String] = []
    }

    struct Snapshot: Sendable {
        let instructions: String
        let tool: any Tool
    }

    private let storage = Locked(Storage())

    var evaluationCount: Int {
        storage.withLock { $0.evaluationCount }
    }

    var executedTools: [String] {
        storage.withLock { $0.executedTools }
    }

    func select(_ selection: Selection) {
        storage.withLock { $0.selection = selection }
    }

    func snapshotForEvaluation() -> Snapshot {
        storage.withLock { storage in
            storage.evaluationCount += 1
            switch storage.selection {
            case .a:
                return Snapshot(
                    instructions: "Instructions A",
                    tool: FixtureTool(name: "tool-a", state: self)
                )
            case .b:
                return Snapshot(
                    instructions: "Instructions B",
                    tool: FixtureTool(name: "tool-b", state: self)
                )
            }
        }
    }

    func recordExecution(_ name: String) {
        storage.withLock { $0.executedTools.append(name) }
    }
}

private struct FixtureTool: Tool {
    let name: String
    let description = "Records which request-scoped tool instance executed"
    let state: DynamicFixtureState

    typealias Arguments = GeneratedContent

    var parameters: GenerationSchema {
        GeneratedContent.generationSchema
    }

    func call(arguments: GeneratedContent) async throws -> String {
        state.recordExecution(name)
        return name
    }
}

private struct DynamicRequestSnapshot: Sendable, Equatable {
    let instructions: String?
    let tools: [String]
}

private struct DynamicContextModel: LanguageModel {
    typealias UnavailableReason = Never

    let state: DynamicFixtureState
    let continuesAfterTool: Bool
    let snapshots = Locked<[DynamicRequestSnapshot]>([])

    func respond<Content>(
        within session: LanguageModelSession,
        to prompt: Prompt,
        generating type: Content.Type,
        includeSchemaInPrompt: Bool,
        options: GenerationOptions
    ) async throws -> LanguageModelSession.Response<Content> where Content: Generable {
        let result = try await run(session: session, type: type)
        return .init(
            content: result.content,
            rawContent: result.raw,
            transcriptEntries: result.entries
        )
    }

    func streamResponse<Content>(
        within session: LanguageModelSession,
        to prompt: Prompt,
        generating type: Content.Type,
        includeSchemaInPrompt: Bool,
        options: GenerationOptions
    ) -> sending LanguageModelSession.ResponseStream<Content> where Content: Generable {
        let stream = AsyncThrowingStream<LanguageModelSession.ResponseStream<Content>.Snapshot, any Error> {
            continuation in
            Task {
                do {
                    let result = try await run(session: session, type: type)
                    continuation.yield(
                        .init(
                            content: result.content.asPartiallyGenerated(),
                            rawContent: result.raw,
                            transcriptEntries: ArraySlice(result.entries)
                        )
                    )
                    continuation.finish()
                } catch {
                    continuation.finish(throwing: error)
                }
            }
        }
        return .init(stream: stream)
    }

    private func run<Content: Generable>(
        session: LanguageModelSession,
        type: Content.Type
    ) async throws -> (content: Content, raw: GeneratedContent, entries: ArraySlice<Transcript.Entry>) {
        let first = session.resolvedRequestContext()
        record(first)
        var entries: [Transcript.Entry] = []

        if continuesAfterTool {
            let tool = try #require(first.tools.first)
            state.select(.b)
            let call = Transcript.ToolCall(
                id: "request-a-call",
                toolName: tool.name,
                arguments: GeneratedContent(properties: [:])
            )
            let output = Transcript.ToolOutput(
                id: call.id,
                toolName: call.toolName,
                segments: try await tool.makeOutputSegments(from: call.arguments)
            )
            entries.append(.toolCalls(.init(id: "request-a-calls", [call])))
            entries.append(.toolOutput(output))

            let continuation = session.resolvedRequestContext()
            record(continuation)
        }

        let raw = GeneratedContent("Done")
        return (try Content(raw), raw, ArraySlice(entries))
    }

    private func record(_ context: LanguageModelSession.RequestContext) {
        snapshots.withLock {
            $0.append(
                .init(
                    instructions: context.instructions?.description,
                    tools: context.tools.map(\.name)
                )
            )
        }
    }
}

private enum DynamicFixtureError: Error, Equatable {
    case failed
}

private struct FailingAfterToolModel: LanguageModel {
    typealias UnavailableReason = Never

    let state: DynamicFixtureState
    let snapshots = Locked<[DynamicRequestSnapshot]>([])
    private let didFail = Locked(false)

    func respond<Content>(
        within session: LanguageModelSession,
        to prompt: Prompt,
        generating type: Content.Type,
        includeSchemaInPrompt: Bool,
        options: GenerationOptions
    ) async throws -> LanguageModelSession.Response<Content> where Content: Generable {
        let context = session.resolvedRequestContext()
        snapshots.withLock {
            $0.append(
                .init(
                    instructions: context.instructions?.description,
                    tools: context.tools.map(\.name)
                )
            )
        }

        let shouldFail = didFail.withLock { didFail in
            defer { didFail = true }
            return !didFail
        }
        if shouldFail {
            let tool = try #require(context.tools.first)
            _ = try await tool.makeOutputSegments(from: GeneratedContent(properties: [:]))
            state.select(.b)
            throw DynamicFixtureError.failed
        }

        let raw = GeneratedContent("Done")
        return .init(content: try Content(raw), rawContent: raw, transcriptEntries: [])
    }

    func streamResponse<Content>(
        within session: LanguageModelSession,
        to prompt: Prompt,
        generating type: Content.Type,
        includeSchemaInPrompt: Bool,
        options: GenerationOptions
    ) -> sending LanguageModelSession.ResponseStream<Content> where Content: Generable {
        let stream = AsyncThrowingStream<LanguageModelSession.ResponseStream<Content>.Snapshot, any Error> {
            $0.finish(throwing: DynamicFixtureError.failed)
        }
        return .init(stream: stream)
    }
}

private final class DynamicCancellationControl: @unchecked Sendable {
    let started: AsyncStream<Void>

    private let startedContinuation: AsyncStream<Void>.Continuation
    private let cancellationContinuation = Locked<CheckedContinuation<Void, any Error>?>(nil)

    init() {
        (started, startedContinuation) = AsyncStream.makeStream()
    }

    func signalStarted() {
        startedContinuation.yield(())
    }

    func waitForCancellation() async throws {
        try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { continuation in
                let isAlreadyCancelled = cancellationContinuation.withLock { stored in
                    guard !Task.isCancelled else { return true }
                    stored = continuation
                    return false
                }
                if isAlreadyCancelled {
                    continuation.resume(throwing: CancellationError())
                }
            }
        } onCancel: {
            let continuation = cancellationContinuation.withLock { stored in
                defer { stored = nil }
                return stored
            }
            continuation?.resume(throwing: CancellationError())
        }
    }
}

private struct CancellingAfterToolModel: LanguageModel {
    typealias UnavailableReason = Never

    let state: DynamicFixtureState
    let control: DynamicCancellationControl
    let snapshots = Locked<[DynamicRequestSnapshot]>([])
    private let didSuspend = Locked(false)

    func respond<Content>(
        within session: LanguageModelSession,
        to prompt: Prompt,
        generating type: Content.Type,
        includeSchemaInPrompt: Bool,
        options: GenerationOptions
    ) async throws -> LanguageModelSession.Response<Content> where Content: Generable {
        let context = session.resolvedRequestContext()
        snapshots.withLock {
            $0.append(
                .init(
                    instructions: context.instructions?.description,
                    tools: context.tools.map(\.name)
                )
            )
        }

        let shouldSuspend = didSuspend.withLock { didSuspend in
            defer { didSuspend = true }
            return !didSuspend
        }
        if shouldSuspend {
            let tool = try #require(context.tools.first)
            _ = try await tool.makeOutputSegments(from: GeneratedContent(properties: [:]))
            state.select(.b)
            control.signalStarted()
            try await control.waitForCancellation()
        }

        let raw = GeneratedContent("Done")
        return .init(content: try Content(raw), rawContent: raw, transcriptEntries: [])
    }

    func streamResponse<Content>(
        within session: LanguageModelSession,
        to prompt: Prompt,
        generating type: Content.Type,
        includeSchemaInPrompt: Bool,
        options: GenerationOptions
    ) -> sending LanguageModelSession.ResponseStream<Content> where Content: Generable {
        let stream = AsyncThrowingStream<LanguageModelSession.ResponseStream<Content>.Snapshot, any Error> {
            $0.finish(throwing: CancellationError())
        }
        return .init(stream: stream)
    }
}

import Testing

@testable import AnyLanguageModel

struct StructuredGenerationTokenCacheTests {
    /// Immutable vocabulary and synchronized observations, safe to share across tasks.
    private struct VocabularyBackend: TokenBackend, Sendable {
        struct Observations: Sendable {
            var textCalls: [Int: Int] = [:]
            var specialCalls: [Int: Int] = [:]
            var masks: [Set<Int>] = []
        }

        let texts: [Int: String]
        let specialTokens: Set<Int>
        let vocabSize: Int
        let observations = Locked(Observations())
        var endTokens: Set<Int> = [63]
        var eosToken: Int { 63 }
        var remainingTokens = 64
        var totalTokenBudget: Int { 64 }
        var queue: [Int] = []

        init(texts: [Int: String], specialTokens: Set<Int> = [], vocabSize: Int = 64) {
            self.texts = texts
            self.specialTokens = specialTokens
            self.vocabSize = vocabSize
        }

        func tokenize(_ text: String) throws -> [Int] {
            texts.first { $0.value == text }.map { [$0.key] } ?? []
        }

        func tokenText(_ token: Int) -> String? {
            observations.withLock { $0.textCalls[token, default: 0] += 1 }
            return texts[token]
        }

        func isSpecialToken(_ token: Int) -> Bool {
            observations.withLock { $0.specialCalls[token, default: 0] += 1 }
            return specialTokens.contains(token)
        }

        mutating func decode(_ token: Int) async throws {
            remainingTokens -= 1
        }

        mutating func sample(from allowedTokens: Set<Int>) async throws -> Int {
            observations.withLock { $0.masks.append(allowedTokens) }
            guard !queue.isEmpty else { throw ConstrainedGenerationError.tokenizationFailed }
            let token = [REDACTED]
            guard allowedTokens.contains(token) else { throw ConstrainedGenerationError.tokenizationFailed }
            return token
        }
    }

    private var baseTexts: [Int: String] {
        var texts = [0: "\"", 1: ",", 2: "}", 3: "]", 4: ":", 15: "-", 16: ".", 63: "<eos>"]
        for digit in 0 ... 9 { texts[5 + digit] = String(digit) }
        return texts
    }

    private func expectEqual(_ lhs: StructuredGenerationTokenSets, _ rhs: StructuredGenerationTokenSets) {
        #expect(lhs.stringContent == rhs.stringContent)
        #expect(lhs.integerContent == rhs.integerContent)
        #expect(lhs.decimalContent == rhs.decimalContent)
    }

    @Test func coldConstructionClassifiesAllSetsInOnePass() {
        let backend = VocabularyBackend(
            texts: [0: "word", 1: "42", 2: "-", 3: ".", 4: "-1.5", 5: "", 6: "9", 7: "\""],
            specialTokens: [6],
            vocabSize: 9
        )
        let tokens = StructuredGenerationTokenCache().tokens(for: backend)
        #expect(tokens.stringContent == [0, 1, 2, 3, 4])
        #expect(tokens.integerContent == [1, 2])
        #expect(tokens.decimalContent == [1, 2, 3, 4])
        let observations = backend.observations.withLock { $0 }
        #expect(observations.specialCalls == Dictionary(uniqueKeysWithValues: (0 ..< 9).map { ($0, 1) }))
        #expect(observations.textCalls == [0: 1, 1: 1, 2: 1, 3: 1, 4: 1, 5: 1, 7: 1, 8: 1])
    }

    private struct ClassificationCase: Sendable {
        let text: String?
        var special = false
        var string = false
        var integer = false
        var decimal = false
    }

    @Test(arguments: [
        ClassificationCase(text: nil),
        ClassificationCase(text: ""),
        ClassificationCase(text: "42", special: true),
        ClassificationCase(text: "42", string: true, integer: true, decimal: true),
        ClassificationCase(text: "-12", string: true, integer: true, decimal: true),
        ClassificationCase(text: "-", string: true, integer: true, decimal: true),
        ClassificationCase(text: ".", string: true, decimal: true),
        ClassificationCase(text: "12.5", string: true, decimal: true),
        ClassificationCase(text: "--", string: true),
        ClassificationCase(text: "-.", string: true),
        ClassificationCase(text: "1-2", string: true, integer: true, decimal: true),
        ClassificationCase(text: "1..2", string: true, decimal: true),
        ClassificationCase(text: "１２", string: true),
        ClassificationCase(text: "²", string: true),
        ClassificationCase(text: "١", string: true),
        ClassificationCase(text: "1e2", string: true),
        ClassificationCase(text: "+1", string: true),
        ClassificationCase(text: " ", string: true),
        ClassificationCase(text: "  "),
        ClassificationCase(text: "\t"),
        ClassificationCase(text: "\n"),
        ClassificationCase(text: "\r"),
        ClassificationCase(text: "\u{00A0}"),
        ClassificationCase(text: " a ", string: true),
        ClassificationCase(text: "a\nb"),
        ClassificationCase(text: "\""),
        ClassificationCase(text: "“"),
        ClassificationCase(text: "’"),
        ClassificationCase(text: "\\"),
        ClassificationCase(text: "\\n"),
        ClassificationCase(text: "】"),
        ClassificationCase(text: "hello", string: true),
        ClassificationCase(text: "é", string: true),
        ClassificationCase(text: "😀", string: true),
    ])
    private func classifierPreservesExistingPolicy(testCase: ClassificationCase) {
        let backend = VocabularyBackend(
            texts: testCase.text.map { [0: $0] } ?? [:],
            specialTokens: testCase.special ? [0] : [],
            vocabSize: 1
        )
        let tokens = StructuredGenerationTokenCache().tokens(for: backend)
        #expect(tokens.stringContent == (testCase.string ? [0] : []))
        #expect(tokens.integerContent == (testCase.integer ? [0] : []))
        #expect(tokens.decimalContent == (testCase.decimal ? [0] : []))
    }

    @Test func noCacheBuildsFreshSetsAndGeneratesCorrectOutput() async throws {
        var backend = VocabularyBackend(texts: baseTexts)
        backend.queue = [6, 2]
        for pass in 1 ... 2 {
            var generator = try ConstrainedJSONGenerator(backend: backend, schema: Int.generationSchema)
            #expect(backend.observations.withLock { $0.specialCalls.values.reduce(0, +) } == pass * 64)
            // Each preceding generation reads the emitted numeric token once.
            #expect(backend.observations.withLock { $0.textCalls.values.reduce(0, +) } == pass * 64 + pass - 1)
            #expect(try await generator.generate() == "1")
        }
    }

    @Test(arguments: [false, true])
    func unsampledNumericDifferenceIsIndependent(reverse: Bool) async throws {
        // Token 20 is absent from the former endpoint, midpoint, EOS, end-token,
        // and individual digit/sign/point samples. All those mappings agree.
        for numeric in (reverse ? [true, false] : [false, true]) {
            var texts = baseTexts
            texts[20] = numeric ? "42" : "word"
            var backend = VocabularyBackend(texts: texts)
            backend.queue = numeric ? [20, 2] : [6, 2]
            let cache = StructuredGenerationTokenCache()
            let tokens = cache.tokens(for: backend)
            #expect(tokens.integerContent == Set(5 ... 15).union(numeric ? [20] : []))
            #expect(tokens.decimalContent == Set(5 ... 16).union(numeric ? [20] : []))
            for schema in [Int.generationSchema, Double.generationSchema] {
                var generator = try ConstrainedJSONGenerator(backend: backend, schema: schema, tokenCache: cache)
                #expect(try await generator.generate() == (numeric ? "42" : "1"))
            }
            #expect(backend.observations.withLock { $0.masks.allSatisfy { $0.contains(20) == numeric } })
        }
    }

    @Test(arguments: [false, true])
    func unsampledStringDifferenceIsIndependent(reverse: Bool) async throws {
        for valid in (reverse ? [true, false] : [false, true]) {
            var texts = baseTexts
            texts[20] = valid ? "word" : "\\"
            var backend = VocabularyBackend(texts: texts, specialTokens: [63])
            backend.queue = [6, 0]
            let cache = StructuredGenerationTokenCache()
            let tokens = cache.tokens(for: backend)
            #expect(tokens.stringContent == Set(1 ... 16).union(valid ? [20] : []))
            var generator = try ConstrainedJSONGenerator(
                backend: backend,
                schema: String.generationSchema,
                tokenCache: cache
            )
            #expect(try await generator.generate() == "\"1\"")
            #expect(backend.observations.withLock { $0.masks.allSatisfy { $0.contains(20) == valid } })
        }
    }

    @Test(arguments: [false, true])
    func specialTokenClassificationBelongsToLoadedVocabulary(reverse: Bool) {
        for special in (reverse ? [true, false] : [false, true]) {
            let backend = VocabularyBackend(texts: [20: "42"], specialTokens: special ? [20] : [])
            let tokens = StructuredGenerationTokenCache().tokens(for: backend)
            #expect(tokens.stringContent == (special ? [] : [20]))
            #expect(tokens.integerContent == (special ? [] : [20]))
            #expect(tokens.decimalContent == (special ? [] : [20]))
        }
    }

    @Test func endTokenChangesReuseContentAndApplyCurrentMasks() async throws {
        var texts = baseTexts
        texts[20] = "word"
        let original = VocabularyBackend(texts: texts, specialTokens: [63])
        let cache = StructuredGenerationTokenCache()
        for ends: Set<Int> in [[20, 6], [63]] {
            var backend = original
            backend.endTokens = ends
            backend.queue = [7, 0]
            var generator = try ConstrainedJSONGenerator(
                backend: backend,
                schema: String.generationSchema,
                tokenCache: cache
            )
            #expect(try await generator.generate() == "\"2\"")
            let masks = backend.observations.withLock { Array($0.masks.suffix(2)) }
            let expectedInitial = Set(1 ... 16).union([20]).subtracting(ends)
            #expect(masks[0] == expectedInitial)
            #expect(masks[1] == expectedInitial.union(ends).union([0]))

            for schema in [Int.generationSchema, Double.generationSchema] {
                backend.queue = [7, 2]
                var number = try ConstrainedJSONGenerator(backend: backend, schema: schema, tokenCache: cache)
                #expect(try await number.generate() == "2")
                // Numeric masks preserve end tokens if their content is numeric.
                #expect(backend.observations.withLock { $0.masks.suffix(2).allSatisfy { $0.contains(6) } })
            }
        }
        #expect(original.observations.withLock { $0.specialCalls.values.reduce(0, +) } == 64)
        #expect(original.observations.withLock { $0.textCalls.values.reduce(0, +) } == 69)
    }

    @Test func vocabularySizesHaveSeparateEntries() {
        let cache = StructuredGenerationTokenCache()
        let small = VocabularyBackend(texts: [0: "42", 2: "1.5"], vocabSize: 2)
        let large = VocabularyBackend(texts: small.texts, vocabSize: 3)
        let first = cache.tokens(for: small)
        #expect(first.stringContent == [0])
        #expect(first.integerContent == [0])
        #expect(first.decimalContent == [0])
        let second = cache.tokens(for: large)
        #expect(second.stringContent == [0, 2])
        #expect(second.integerContent == [0])
        #expect(second.decimalContent == [0, 2])
        expectEqual(cache.tokens(for: small), first)
        #expect(small.observations.withLock { $0.specialCalls == [0: 1, 1: 1] })
        #expect(large.observations.withLock { $0.specialCalls == [0: 1, 1: 1, 2: 1] })
    }

    @Test func concurrentFirstUsePerformsExactlyOneScan() async {
        let backend = VocabularyBackend(texts: [20: "42", 21: "."], specialTokens: [63])
        let cache = StructuredGenerationTokenCache()
        await withTaskGroup(of: StructuredGenerationTokenSets.self) { group in
            for _ in 0 ..< 32 {
                group.addTask { cache.tokens(for: backend) }
            }
            for await tokens in group {
                #expect(tokens.stringContent == [20, 21])
                #expect(tokens.integerContent == [20])
                #expect(tokens.decimalContent == [20, 21])
