        #expect(releasedCache == nil)
    }

    @Test func structuralValidationPrecedesScanning() {
        let backend = VocabularyBackend(texts: [0: "\"", 1: ","])
        #expect(throws: ConstrainedGenerationError.self) {
            _ = try ConstrainedJSONGenerator(
                backend: backend,
